WITH canon AS (
    SELECT
        COALESCE(TO_VARCHAR(CAST(branchid AS NUMBER(38, 0))), CHR(30)) AS c_branchid,
        COALESCE(CAST(branchname AS VARCHAR), CHR(30)) AS c_branchname,
        COALESCE(CAST(branchlocation AS VARCHAR), CHR(30)) AS c_branchlocation
    FROM dwh.dimbranch
),

hashed AS (
    SELECT
        CONCAT_WS(CHR(31), c_branchid) AS row_key,
        SHA2(CONCAT_WS(CHR(31), c_branchid, c_branchname, c_branchlocation), 256) AS row_hash,
        SHA2(CONCAT_WS(CHR(31), c_branchid), 256) AS key_hash
    FROM canon
)

SELECT
    row_key,
    row_hash
FROM hashed
ORDER BY row_key, row_hash;
